import type { MonthCoverage } from './data/coverage';
import type { Group } from './data/demography_groups';

// ~~~~~~~~~~ shapes of the JSON files in /public/data ~~~~~~~~~~

/** [west, south, east, north] in degrees */
export type BoundingBox = [number, number, number, number];

/**
 * lsoa_index.json: every LSOA on the map, as parallel lists, generated by
 * data_processing/scripts/geojson_maker.mjs. The shapes themselves are in
 * lsoa_boundaries.json, which only the map reads.
 */
export interface LsoaIndex {
    lsoa: string[];
    name: string[];
    bbox: BoundingBox[];
}

/** One neighbourhood (LSOA) on the map */
export interface LsoaArea {
    lsoa: string;
    lsoaNM: string;
    bbox: BoundingBox;
}

/** Crime counts for one LSOA, keyed by crime id (an index into crime_lookup). */
export type CrimeCounts = Record<string, number>;

/** crime/YYYY-MM.json */
export interface MonthCrimeData {
    crime_lookup: string[];
    lsoa: Record<string, CrimeCounts>;
}

/** One LSOA in LSOA_2021_demography.json: residents per group plus the total. */
export type LsoaDemography = Partial<Record<Group, number>> & { total_population: number };

/** LSOA_2021_demography.json */
export type Demography = Record<string, LsoaDemography>;

/** crime_group_correlation.json, generated by data_processing/scripts/correlation_maker.mjs */
export interface CrimeGroupCorrelation {
    first_month: string;
    last_month: string;
    areas: number;
    crime_lookup: string[];
    groups: Group[];
    /** [crime_id][group index] Spearman ρ against that crime's share of local crime */
    mix: number[][];
    /** [crime_id][group index] Spearman ρ against that crime per 1,000 residents */
    rate: number[][];
}

/** crime_deprivation_correlation.json, generated by data_processing/scripts/correlation_maker.mjs */
export interface CrimeDeprivationCorrelation {
    first_month: string;
    last_month: string;
    areas: number;
    crime_lookup: string[];
    /** Spearman ρ between the deprivation score and all crime per 1,000 residents */
    all_crime_rate: number;
    /** [crime_id] Spearman ρ between the deprivation score and that crime's share of local crime */
    mix: number[];
    /** [crime_id] Spearman ρ between the deprivation score and that crime per 1,000 residents */
    rate: number[];
}

// ~~~~~~~~~~ derived in the app ~~~~~~~~~~

export interface GroupCorrelation {
    group: Group;
    rho: number;
}

export interface GroupMonthCorrelation extends GroupCorrelation {
    /** ρ once deprivation is taken out (partial Spearman correlation) */
    adjusted_rho: number;
    /** ρ between the group's share of residents and the deprivation score */
    rho_with_deprivation: number;
}

/** Crime in one tenth of neighbourhoods, ordered by deprivation */
export interface DeprivationDecile {
    /** 1 = least deprived tenth … 10 = most deprived */
    decile: number;
    /** Crimes per 1,000 residents across the decile's neighbourhoods */
    rate: number;
    min_score: number;
    max_score: number;
}

export interface CorrelationResult {
    areas: number;
    groups: GroupMonthCorrelation[];
    deprivation: {
        /** Spearman ρ between the deprivation score and crimes per 1,000 residents */
        rho: number;
        deciles: DeprivationDecile[];
    };
}

/** Everything derived from one month's crime dataset. */
export interface MonthSummary {
    month: string;
    crime_data: MonthCrimeData;
    /** Which LSOAs have published crime data this month */
    coverage: MonthCoverage;
    countryCrime: number;
    correlations: CorrelationResult;
}
